inline void drawBitmap1BitFast(int x, int y, const uint8_t *bitmap, int w, int h, uint16_t color)
{
  int byteWidth = (w + 7) / 8;
  for (int j = 0; j < h; j++)
  {
    int start_x = -1;
    int len = 0;
    for (int i = 0; i < w; i++)
    {
      uint8_t b = pgm_read_byte(&bitmap[j * byteWidth + (i / 8)]);
      if (b & (0x80 >> (i % 8)))
      {
        if (start_x < 0) { start_x = i; len = 1; }
        else { len++; }
      }
      else
      {
        if (start_x >= 0)
        {
          tft.drawFastHLine(x + start_x, y + j, len, color);
          start_x = -1;
          len = 0;
        }
      }
    }
    if (start_x >= 0)
    {
      tft.drawFastHLine(x + start_x, y + j, len, color);
    }
  }
}

// Find glyph in PROGMEM table
inline const ArabicGlyph* findArabicGlyph(uint16_t codepoint)
{
  for (int i = 0; i < ARABIC_GLYPH_COUNT; i++)
  {
    uint16_t cp = pgm_read_word(&ARABIC_GLYPH_TABLE[i].codepoint);
    if (cp == codepoint)
    {
      return &ARABIC_GLYPH_TABLE[i];
    }
  }
  return nullptr;
}

// Reshape Arabic UTF-8 string into Presentation Forms-B glyph IDs
int reshapeArabicUTF8(const String &utf8_str, uint16_t *out_glyphs, int max_len)
{
  // First decode UTF-8 to codepoints
  int in_len = utf8_str.length();
  uint16_t codepoints[128];
  int cp_count = 0;

  int idx = 0;
  while (idx < in_len && cp_count < 127)
  {
    uint8_t c = (uint8_t)utf8_str[idx];
    if (c < 0x80)
    {
      codepoints[cp_count++] = c;
      idx++;
    }
    else if ((c & 0xE0) == 0xC0 && idx + 1 < in_len)
    {
      uint16_t cp = ((c & 0x1F) << 6) | (utf8_str[idx + 1] & 0x3F);
      codepoints[cp_count++] = cp;
      idx += 2;
    }
    else if ((c & 0xF0) == 0xE0 && idx + 2 < in_len)
    {
      uint16_t cp = ((c & 0x0F) << 12) | ((utf8_str[idx + 1] & 0x3F) << 6) | (utf8_str[idx + 2] & 0x3F);
      codepoints[cp_count++] = cp;
      idx += 3;
    }
    else
    {
      idx++;
    }
  }

  // Handle Lam-Alef ligatures & Reshaping
  int out_count = 0;
  for (int i = 0; i < cp_count && out_count < max_len; i++)
  {
    uint16_t cp = codepoints[i];

    // Check Lam-Alef
    if (cp == 0x0644 && i + 1 < cp_count)
    {
      uint16_t next_cp = codepoints[i + 1];
      uint16_t la_iso = 0, la_fin = 0;
      if (next_cp == 0x0622) { la_iso = 0xFEF5; la_fin = 0xFEF6; }
      else if (next_cp == 0x0623) { la_iso = 0xFEF7; la_fin = 0xFEF8; }
      else if (next_cp == 0x0625) { la_iso = 0xFEF9; la_fin = 0xFEFA; }
      else if (next_cp == 0x0627) { la_iso = 0xFEFB; la_fin = 0xFEFC; }

      if (la_iso != 0)
      {
        bool prev_connects = false;
        if (i > 0)
        {
          for (int s = 0; s < ARABIC_SHAPE_COUNT; s++)
          {
            if (pgm_read_word(&ARABIC_SHAPES[s].unicode) == codepoints[i - 1])
            {
              prev_connects = (pgm_read_byte(&ARABIC_SHAPES[s].connects_next) != 0);
              break;
            }
          }
        }
        out_glyphs[out_count++] = prev_connects ? la_fin : la_iso;
        i++; // skip Alef
        continue;
      }
    }

    // Find shape in table
    int shape_idx = -1;
    for (int s = 0; s < ARABIC_SHAPE_COUNT; s++)
    {
      if (pgm_read_word(&ARABIC_SHAPES[s].unicode) == cp)
      {
        shape_idx = s;
        break;
      }
    }

    if (shape_idx < 0)
    {
      // ASCII / punctuation
      out_glyphs[out_count++] = cp;
      continue;
    }

    bool prev_connects = false;
    if (i > 0)
    {
      for (int s = 0; s < ARABIC_SHAPE_COUNT; s++)
      {
        if (pgm_read_word(&ARABIC_SHAPES[s].unicode) == codepoints[i - 1])
        {
          prev_connects = (pgm_read_byte(&ARABIC_SHAPES[s].connects_next) != 0);
          break;
        }
      }
    }

    bool next_connects = false;
    if (i + 1 < cp_count)
    {
      for (int s = 0; s < ARABIC_SHAPE_COUNT; s++)
      {
        if (pgm_read_word(&ARABIC_SHAPES[s].unicode) == codepoints[i + 1])
        {
          next_connects = (pgm_read_byte(&ARABIC_SHAPES[s].connects_prev) != 0);
          break;
        }
      }
    }

    if (prev_connects && next_connects)
    {
      out_glyphs[out_count++] = pgm_read_word(&ARABIC_SHAPES[shape_idx].medial_form);
    }
    else if (prev_connects)
    {
      out_glyphs[out_count++] = pgm_read_word(&ARABIC_SHAPES[shape_idx].final_form);
    }
    else if (next_connects)
    {
      out_glyphs[out_count++] = pgm_read_word(&ARABIC_SHAPES[shape_idx].initial_form);
    }
    else
    {
      out_glyphs[out_count++] = pgm_read_word(&ARABIC_SHAPES[shape_idx].isolated);
    }
  }

  return out_count;
}

// Draw dynamic Arabic text on TFT
void drawArabicDynamicText(const String &utf8_str, int center_x, int top_y, uint16_t color)
{
  uint16_t glyphs[128];
  int count = reshapeArabicUTF8(utf8_str, glyphs, 128);
  if (count <= 0) return;

  // Calculate total width
  int total_w = 0;
  for (int i = 0; i < count; i++)
  {
    const ArabicGlyph *g = findArabicGlyph(glyphs[i]);
    if (g)
    {
      total_w += pgm_read_byte(&g->width) + 1;
    }
    else if (glyphs[i] == ' ')
    {
      total_w += 6;
    }
    else
    {
      total_w += 8;
    }
  }

  // Draw RTL: First letter of Arabic starts at right
  int cur_x = center_x + (total_w / 2);

  for (int i = 0; i < count; i++)
  {
    uint16_t cp = glyphs[i];
    if (cp == ' ')
    {
      cur_x -= 6;
      continue;
    }

    const ArabicGlyph *g = findArabicGlyph(cp);
    if (!g)
    {
      cur_x -= 8;
      continue;
    }

    uint8_t gw = pgm_read_byte(&g->width);
    uint8_t gh = pgm_read_byte(&g->height);
    int8_t gy = pgm_read_byte(&g->y_offset);
    uint16_t offset = pgm_read_word(&g->data_offset);

    cur_x -= gw;

    if (offset != 0xFFFF)
    {
      drawBitmap1BitFast(cur_x, top_y + gy, &ARABIC_GLYPH_BITMAPS[offset], gw, gh, color);
    }

    cur_x -= 1; // 1px tracking
  }
}

#endif // ARABIC_FONT_H
